// UpdateVersion sets the "version" field to the value that was provided on create.
func (u *OntOntologyUpsertBulk) UpdateVersion() *OntOntologyUpsertBulk {
	return u.Update(func(s *OntOntologyUpsert) {
		s.UpdateVersion()
	})
}

// ClearVersion clears the value of the "version" field.
func (u *OntOntologyUpsertBulk) ClearVersion() *OntOntologyUpsertBulk {
	return u.Update(func(s *OntOntologyUpsert) {
		s.ClearVersion()
	})
}

// Exec executes the query.
func (u *OntOntologyUpsertBulk) Exec(ctx context.Context) error {
	if u.create.err != nil {
		return u.create.err
	}
	for i, b := range u.create.builders {
		if len(b.conflict) != 0 {
			return fmt.Errorf("ent: OnConflict was set for builder %d. Set it on the OntOntologyCreateBulk instead", i)
		}
	}
	if len(u.create.conflict) == 0 {
		return errors.New("ent: missing options for OntOntologyCreateBulk.OnConflict")
	}
	return u.create.Exec(ctx)
}

// ExecX is like Exec, but panics if an error occurs.
func (u *OntOntologyUpsertBulk) ExecX(ctx context.Context) {
	if err := u.create.Exec(ctx); err != nil {
		panic(err)
	}
}
